create extension if not exists pgcrypto;
create schema if not exists private;
create schema if not exists finance;

create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,status text not null default 'active' check(status in('active','suspended','archived')),created_at timestamptz not null default now());
create table if not exists public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.memberships(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('owner','access_admin','manager','operator','purchasing','finance','auditor')),status text not null default 'active' check(status in('invited','active','revoked')),expires_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,user_id));
create table if not exists public.units(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,name text not null,code text not null,status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,id));
create table if not exists public.locations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,unit_id uuid not null,name text not null,type text not null default 'warehouse' check(type in('warehouse','bar','kitchen','event','vehicle','quarantine','other')),is_stockable boolean not null default true,status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,unit_id) references public.units(tenant_id,id) on delete cascade);
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,name text not null,family text not null default 'insumo' check(family in('bebida','alimento','insumo','descartavel','equipamento','utensilio','evento','apoio')),created_at timestamptz not null default now(),unique(tenant_id,name),unique(tenant_id,id));
create table if not exists public.items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,category_id uuid,sku text not null,name text not null,nature text not null default 'consumable' check(nature in('consumable','returnable','asset','service')),family text not null default 'insumo' check(family in('bebida','alimento','insumo','descartavel','equipamento','utensilio','evento','apoio')),base_uom text not null check(base_uom in('g','ml','un','m')),status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),unique(tenant_id,sku),unique(tenant_id,id),foreign key(tenant_id,category_id) references public.categories(tenant_id,id) on delete set null);
create table if not exists public.item_packages(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,item_id uuid not null,name text not null,factor numeric(20,6) not null check(factor>0),barcode text,created_at timestamptz not null default now(),foreign key(tenant_id,item_id) references public.items(tenant_id,id) on delete cascade);
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,name text not null,tax_id text,email text,phone text,status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),unique(tenant_id,id));
create table if not exists public.supplier_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,supplier_id uuid not null,item_id uuid not null,supplier_sku text,lead_time_days int not null default 0 check(lead_time_days>=0),last_unit_cost numeric(20,6),created_at timestamptz not null default now(),unique(tenant_id,supplier_id,item_id),foreign key(tenant_id,supplier_id) references public.suppliers(tenant_id,id) on delete cascade,foreign key(tenant_id,item_id) references public.items(tenant_id,id) on delete cascade);
create table if not exists public.item_location_policies(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,item_id uuid not null,location_id uuid not null,min_q numeric(20,6) not null default 0 check(min_q>=0),max_q numeric(20,6) not null default 0 check(max_q>=0),reorder_q numeric(20,6) not null default 0 check(reorder_q>=0),created_at timestamptz not null default now(),unique(tenant_id,item_id,location_id),foreign key(tenant_id,item_id) references public.items(tenant_id,id) on delete cascade,foreign key(tenant_id,location_id) references public.locations(tenant_id,id) on delete cascade);
create table if not exists public.lots(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,item_id uuid not null,lot_code text not null,expires_on date,condition text not null default 'usable' check(condition in('usable','quarantine','damaged','expired')),created_at timestamptz not null default now(),unique(tenant_id,item_id,lot_code),unique(tenant_id,id),foreign key(tenant_id,item_id) references public.items(tenant_id,id) on delete cascade);
create table if not exists public.stock_positions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,item_id uuid not null,location_id uuid not null,lot_id uuid not null,condition text not null default 'usable' check(condition in('usable','quarantine','damaged','expired')),on_hand_q numeric(20,6) not null default 0 check(on_hand_q>=0),reserved_q numeric(20,6) not null default 0 check(reserved_q>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,item_id,location_id,lot_id,condition),unique(tenant_id,id),foreign key(tenant_id,item_id) references public.items(tenant_id,id) on delete cascade,foreign key(tenant_id,location_id) references public.locations(tenant_id,id) on delete cascade,foreign key(tenant_id,lot_id) references public.lots(tenant_id,id) on delete cascade,check(reserved_q<=on_hand_q));
create table if not exists public.stock_documents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,document_no text not null,type text not null check(type in('opening','receipt','consumption','loss','transfer','return','adjustment','count')),status text not null default 'posted' check(status in('draft','posted','voided')),reason text,idempotency_key text not null,actor_id uuid not null references auth.users(id),posted_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(tenant_id,document_no),unique(tenant_id,idempotency_key),unique(tenant_id,id));
create table if not exists public.stock_document_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,document_id uuid not null,item_id uuid not null,location_id uuid not null,to_location_id uuid,lot_id uuid not null,quantity numeric(20,6) not null check(quantity>0),input_uom text not null,signed_quantity numeric(20,6) not null,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,document_id) references public.stock_documents(tenant_id,id) on delete cascade,foreign key(tenant_id,item_id) references public.items(tenant_id,id),foreign key(tenant_id,location_id) references public.locations(tenant_id,id),foreign key(tenant_id,to_location_id) references public.locations(tenant_id,id),foreign key(tenant_id,lot_id) references public.lots(tenant_id,id));
create table if not exists public.stock_entries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,document_id uuid not null,document_line_id uuid not null,item_id uuid not null,location_id uuid not null,lot_id uuid not null,quantity numeric(20,6) not null,direction text not null check(direction in('in','out')),created_at timestamptz not null default now(),foreign key(tenant_id,document_id) references public.stock_documents(tenant_id,id),foreign key(tenant_id,document_line_id) references public.stock_document_lines(tenant_id,id));

create table if not exists public.events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,name text not null,code text not null,venue text,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'planned' check(status in('planned','separating','dispatched','operating','settling','closed','reopened','cancelled')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,id),check(ends_at>=starts_at));
create table if not exists public.event_plan_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,event_id uuid not null,item_id uuid not null,planned_q numeric(20,6) not null check(planned_q>0),created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,event_id) references public.events(tenant_id,id) on delete cascade,foreign key(tenant_id,item_id) references public.items(tenant_id,id));
create table if not exists public.reservations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,event_id uuid not null,item_id uuid not null,location_id uuid not null,quantity numeric(20,6) not null check(quantity>0),status text not null default 'firm' check(status in('draft','firm','released','consumed')),created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,event_id) references public.events(tenant_id,id) on delete cascade,foreign key(tenant_id,item_id) references public.items(tenant_id,id),foreign key(tenant_id,location_id) references public.locations(tenant_id,id));
create table if not exists public.reservation_allocations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,reservation_id uuid not null,lot_id uuid not null,quantity numeric(20,6) not null check(quantity>0),created_at timestamptz not null default now(),unique(tenant_id,reservation_id,lot_id),unique(tenant_id,id),foreign key(tenant_id,reservation_id) references public.reservations(tenant_id,id) on delete cascade,foreign key(tenant_id,lot_id) references public.lots(tenant_id,id));
create table if not exists public.purchase_requests(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,requested_by uuid not null references auth.users(id),status text not null default 'requested' check(status in('requested','approved','rejected','ordered','received','cancelled')),needed_by date,reason text,created_at timestamptz not null default now(),unique(tenant_id,id));
create table if not exists public.purchase_request_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,request_id uuid not null,item_id uuid not null,location_id uuid not null,quantity numeric(20,6) not null check(quantity>0),created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,request_id) references public.purchase_requests(tenant_id,id) on delete cascade,foreign key(tenant_id,item_id) references public.items(tenant_id,id),foreign key(tenant_id,location_id) references public.locations(tenant_id,id));
create table if not exists public.purchase_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,supplier_id uuid not null,request_id uuid,order_no text not null,status text not null default 'draft' check(status in('draft','sent','partial','received','cancelled')),created_at timestamptz not null default now(),unique(tenant_id,order_no),unique(tenant_id,id),foreign key(tenant_id,supplier_id) references public.suppliers(tenant_id,id),foreign key(tenant_id,request_id) references public.purchase_requests(tenant_id,id));
create table if not exists public.purchase_order_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,order_id uuid not null,item_id uuid not null,ordered_q numeric(20,6) not null check(ordered_q>0),received_q numeric(20,6) not null default 0 check(received_q>=0 and received_q<=ordered_q),unit_cost numeric(20,6),created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,order_id) references public.purchase_orders(tenant_id,id) on delete cascade,foreign key(tenant_id,item_id) references public.items(tenant_id,id));
create table if not exists public.receipts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,order_id uuid not null,location_id uuid not null,status text not null default 'draft' check(status in('draft','checking','posted','rejected')),received_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,order_id) references public.purchase_orders(tenant_id,id),foreign key(tenant_id,location_id) references public.locations(tenant_id,id));
create table if not exists public.receipt_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,receipt_id uuid not null,order_line_id uuid not null,lot_id uuid not null,accepted_q numeric(20,6) not null default 0 check(accepted_q>=0),rejected_q numeric(20,6) not null default 0 check(rejected_q>=0),created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,receipt_id) references public.receipts(tenant_id,id) on delete cascade,foreign key(tenant_id,order_line_id) references public.purchase_order_lines(tenant_id,id),foreign key(tenant_id,lot_id) references public.lots(tenant_id,id));
create table if not exists public.assets(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,item_id uuid not null,asset_tag text not null,condition text not null default 'usable' check(condition in('usable','quarantine','damaged','lost','retired')),status text not null default 'available' check(status in('available','reserved','dispatched','returned','retired')),created_at timestamptz not null default now(),unique(tenant_id,asset_tag),unique(tenant_id,id),foreign key(tenant_id,item_id) references public.items(tenant_id,id));
create table if not exists public.asset_custodies(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,asset_id uuid not null,location_id uuid,event_id uuid,responsible_user uuid references auth.users(id),opened_at timestamptz not null default now(),closed_at timestamptz,condition_out text,condition_in text,unique(tenant_id,id),foreign key(tenant_id,asset_id) references public.assets(tenant_id,id) on delete cascade,foreign key(tenant_id,location_id) references public.locations(tenant_id,id),foreign key(tenant_id,event_id) references public.events(tenant_id,id),check(closed_at is null or closed_at>=opened_at));
create unique index if not exists one_open_asset_custody on public.asset_custodies(tenant_id,asset_id) where closed_at is null;
create table if not exists public.alerts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,kind text not null check(kind in('rupture','expiry','event_shortage','purchase_delay','return_pending','count_pending')),item_id uuid,event_id uuid,status text not null default 'new' check(status in('new','acknowledged','resolved')),dedupe_key text not null,message text not null,created_at timestamptz not null default now(),resolved_at timestamptz,unique(tenant_id,dedupe_key),foreign key(tenant_id,item_id) references public.items(tenant_id,id),foreign key(tenant_id,event_id) references public.events(tenant_id,id));
create table if not exists public.audit_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),action text not null,entity text not null,entity_id uuid,correlation_id uuid not null default gen_random_uuid(),payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create view public.activity_feed with(security_invoker=true) as select d.id,d.tenant_id,d.type,d.reason,d.document_no,d.actor_id,d.posted_at as created_at,coalesce(string_agg(distinct i.name,', ' order by i.name),'Movimentação') as label,coalesce(string_agg(distinct l.name,', ' order by l.name),'') as location_name from public.stock_documents d left join public.stock_document_lines dl on dl.tenant_id=d.tenant_id and dl.document_id=d.id left join public.items i on i.tenant_id=dl.tenant_id and i.id=dl.item_id left join public.locations l on l.tenant_id=dl.tenant_id and l.id=dl.location_id group by d.id;
create table if not exists finance.stock_values(tenant_id uuid not null references public.organizations(id) on delete cascade,item_id uuid not null,location_id uuid not null,avg_unit_cost numeric(20,6) not null default 0,stock_value numeric(20,6) not null default 0,updated_at timestamptz not null default now(),primary key(tenant_id,item_id,location_id));

create index if not exists idx_memberships_user on public.memberships(user_id,status);
create index if not exists idx_positions_tenant on public.stock_positions(tenant_id,location_id,item_id);
create index if not exists idx_lots_expiry on public.lots(tenant_id,expires_on,condition);
create index if not exists idx_documents_tenant on public.stock_documents(tenant_id,posted_at desc);
create index if not exists idx_events_tenant on public.events(tenant_id,status,starts_at);
create or replace function private.is_member(p_tenant uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.memberships m where m.tenant_id=p_tenant and m.user_id=auth.uid() and m.status='active' and (m.expires_at is null or m.expires_at>now())); $$;

create or replace function public.bootstrap_workspace(p_name text default 'Operação Farol') returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare v_uid uuid:=auth.uid(); v_org uuid; v_unit uuid; v_bar uuid; v_wh uuid; v_cat uuid; v_item uuid; v_lot uuid;
begin
 if v_uid is null then raise exception 'not_authenticated'; end if;
 select tenant_id into v_org from memberships where user_id=v_uid and status='active' limit 1;
 if v_org is not null then return v_org; end if;
 insert into organizations(name) values(coalesce(nullif(trim(p_name),''),'Operação Farol')) returning id into v_org;
 insert into profiles(user_id,display_name,email) select v_uid,coalesce(raw_user_meta_data->>'name','Operador'),email from auth.users where id=v_uid on conflict(user_id) do nothing;
 insert into memberships(tenant_id,user_id,role) values(v_org,v_uid,'owner');
 insert into units(tenant_id,name,code) values(v_org,'Unidade principal','U01') returning id into v_unit;
 insert into locations(tenant_id,unit_id,name,type) values(v_org,v_unit,'Bar principal','bar') returning id into v_bar;
 insert into locations(tenant_id,unit_id,name,type) values(v_org,v_unit,'Depósito central','warehouse') returning id into v_wh;
 insert into categories(tenant_id,name,family) values(v_org,'Bebidas','bebida') returning id into v_cat;
 insert into items(tenant_id,category_id,sku,name,nature,family,base_uom) values(v_org,v_cat,'BEV-001','Água sem gás 500 ml','consumable','bebida','ml') returning id into v_item;
 insert into item_packages(tenant_id,item_id,name,factor) values(v_org,v_item,'Caixa com 12 unidades',6000);
 insert into item_location_policies(tenant_id,item_id,location_id,min_q,max_q,reorder_q) values(v_org,v_item,v_bar,6000,24000,12000),(v_org,v_item,v_wh,12000,60000,24000);
 insert into lots(tenant_id,item_id,lot_code,expires_on) values(v_org,v_item,'LOTE-DEMO-001',current_date+180) returning id into v_lot;
 insert into stock_positions(tenant_id,item_id,location_id,lot_id,on_hand_q) values(v_org,v_item,v_bar,v_lot,12000),(v_org,v_item,v_wh,v_lot,36000);
 insert into finance.stock_values(tenant_id,item_id,location_id,avg_unit_cost,stock_value) values(v_org,v_item,v_bar,.004,48),(v_org,v_item,v_wh,.004,144);
 insert into audit_events(tenant_id,actor_id,action,entity,payload) values(v_org,v_uid,'workspace.bootstrap','organization',jsonb_build_object('synthetic_data',true));
 return v_org;
end; $$;

create or replace function public.post_stock_movement(p_type text,p_item_id uuid,p_location_id uuid,p_to_location_id uuid default null,p_lot_id uuid default null,p_quantity numeric default 0,p_input_uom text default null,p_reason text default null,p_idempotency_key text default null) returns jsonb language plpgsql security definer set search_path=public,finance,pg_temp as $$
declare v_uid uuid:=auth.uid(); v_tenant uuid; v_lot uuid; v_doc uuid; v_line uuid; v_no text; v_uom text; v_qty numeric:=p_quantity; v_factor numeric:=1; v_pos uuid; v_on numeric; v_reserved numeric; v_existing jsonb;
begin
 if v_uid is null then raise exception 'not_authenticated'; end if;
 if p_quantity is null or p_quantity<=0 then raise exception 'quantity_must_be_positive'; end if;
 select tenant_id into v_tenant from memberships where user_id=v_uid and status='active' and (expires_at is null or expires_at>now()) limit 1;
 if v_tenant is null then raise exception 'membership_required'; end if;
 if p_idempotency_key is not null then select jsonb_build_object('document_id',id,'document_no',document_no) into v_existing from stock_documents where tenant_id=v_tenant and idempotency_key=p_idempotency_key; if v_existing is not null then return v_existing; end if; end if;
 select base_uom into v_uom from items where tenant_id=v_tenant and id=p_item_id and status='active'; if v_uom is null then raise exception 'item_not_found'; end if;
 if p_input_uom is not null and p_input_uom<>v_uom then select factor into v_factor from item_packages where tenant_id=v_tenant and item_id=p_item_id and name=p_input_uom limit 1; if v_factor is null then raise exception 'conversion_not_configured'; end if; end if;
 v_qty:=p_quantity*v_factor;
 if p_lot_id is null then insert into lots(tenant_id,item_id,lot_code) values(v_tenant,p_item_id,'MOV-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')) returning id into v_lot; else select id into v_lot from lots where tenant_id=v_tenant and id=p_lot_id and item_id=p_item_id for update; end if; if v_lot is null then raise exception 'lot_not_found'; end if;
 if p_type='transfer' and (p_to_location_id is null or p_to_location_id=p_location_id) then raise exception 'destination_required'; end if;
 v_no:='MOV-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||substr(replace(gen_random_uuid()::text,'-',''),1,6);
 insert into stock_documents(tenant_id,document_no,type,reason,idempotency_key,actor_id) values(v_tenant,v_no,p_type,p_reason,coalesce(p_idempotency_key,gen_random_uuid()::text),v_uid) returning id into v_doc;
 insert into stock_document_lines(tenant_id,document_id,item_id,location_id,to_location_id,lot_id,quantity,input_uom,signed_quantity) values(v_tenant,v_doc,p_item_id,p_location_id,p_to_location_id,v_lot,v_qty,coalesce(p_input_uom,v_uom),case when p_type in('consumption','loss','transfer') then -v_qty else v_qty end) returning id into v_line;
 select id,on_hand_q,reserved_q into v_pos,v_on,v_reserved from stock_positions where tenant_id=v_tenant and item_id=p_item_id and location_id=p_location_id and lot_id=v_lot and condition='usable' for update;
 if p_type in('consumption','loss','transfer') then if v_pos is null or v_on-v_reserved<v_qty then raise exception 'insufficient_available_stock'; end if; update stock_positions set on_hand_q=on_hand_q-v_qty,updated_at=now() where id=v_pos; insert into stock_entries(tenant_id,document_id,document_line_id,item_id,location_id,lot_id,quantity,direction) values(v_tenant,v_doc,v_line,p_item_id,p_location_id,v_lot,v_qty,'out'); end if;
 if p_type in('opening','receipt','adjustment','transfer','return') then if p_type='transfer' then insert into stock_positions(tenant_id,item_id,location_id,lot_id,on_hand_q) values(v_tenant,p_item_id,p_to_location_id,v_lot,v_qty) on conflict(tenant_id,item_id,location_id,lot_id,condition) do update set on_hand_q=stock_positions.on_hand_q+excluded.on_hand_q,updated_at=now(); insert into stock_entries(tenant_id,document_id,document_line_id,item_id,location_id,lot_id,quantity,direction) values(v_tenant,v_doc,v_line,p_item_id,p_to_location_id,v_lot,v_qty,'in'); else insert into stock_positions(tenant_id,item_id,location_id,lot_id,on_hand_q) values(v_tenant,p_item_id,p_location_id,v_lot,v_qty) on conflict(tenant_id,item_id,location_id,lot_id,condition) do update set on_hand_q=stock_positions.on_hand_q+excluded.on_hand_q,updated_at=now(); insert into stock_entries(tenant_id,document_id,document_line_id,item_id,location_id,lot_id,quantity,direction) values(v_tenant,v_doc,v_line,p_item_id,p_location_id,v_lot,v_qty,'in'); end if; end if;
 insert into audit_events(tenant_id,actor_id,action,entity,entity_id,payload) values(v_tenant,v_uid,'stock.movement','stock_document',v_doc,jsonb_build_object('type',p_type,'quantity',v_qty,'item_id',p_item_id));
 return jsonb_build_object('document_id',v_doc,'document_no',v_no,'quantity',v_qty);
end; $$;

alter table public.organizations enable row level security; alter table public.profiles enable row level security; alter table public.memberships enable row level security; alter table public.units enable row level security; alter table public.locations enable row level security; alter table public.categories enable row level security; alter table public.items enable row level security; alter table public.item_packages enable row level security; alter table public.suppliers enable row level security; alter table public.supplier_items enable row level security; alter table public.item_location_policies enable row level security; alter table public.lots enable row level security; alter table public.stock_positions enable row level security; alter table public.stock_documents enable row level security; alter table public.stock_document_lines enable row level security; alter table public.stock_entries enable row level security; alter table public.events enable row level security; alter table public.event_plan_lines enable row level security; alter table public.reservations enable row level security; alter table public.reservation_allocations enable row level security; alter table public.purchase_requests enable row level security; alter table public.purchase_request_lines enable row level security; alter table public.purchase_orders enable row level security; alter table public.purchase_order_lines enable row level security; alter table public.receipts enable row level security; alter table public.receipt_lines enable row level security; alter table public.assets enable row level security; alter table public.asset_custodies enable row level security; alter table public.alerts enable row level security; alter table public.audit_events enable row level security; alter table finance.stock_values enable row level security;

drop policy if exists tenant_select on public.organizations; create policy tenant_select on public.organizations for select to authenticated using(private.is_member(id));
do $$ declare t text; begin foreach t in array array['units','locations','categories','items','item_packages','suppliers','supplier_items','item_location_policies','lots','stock_positions','stock_documents','stock_document_lines','stock_entries','events','event_plan_lines','reservations','reservation_allocations','purchase_requests','purchase_request_lines','purchase_orders','purchase_order_lines','receipts','receipt_lines','assets','asset_custodies','alerts','audit_events'] loop execute format('drop policy if exists tenant_select on public.%I',t); execute format('create policy tenant_select on public.%I for select to authenticated using(private.is_member(tenant_id))',t); end loop; end $$;
drop policy if exists profile_self on public.profiles; create policy profile_self on public.profiles for select to authenticated using(user_id=auth.uid());
drop policy if exists membership_self on public.memberships; create policy membership_self on public.memberships for select to authenticated using(user_id=auth.uid() or private.is_member(tenant_id));
revoke all on all tables in schema public from anon; revoke all on all tables in schema finance from anon,authenticated; grant usage on schema public to authenticated; grant select on all tables in schema public to authenticated; grant select on public.activity_feed to authenticated; revoke all on function public.bootstrap_workspace(text) from public,anon; grant execute on function public.bootstrap_workspace(text) to authenticated; revoke all on function public.post_stock_movement(text,uuid,uuid,uuid,uuid,numeric,text,text,text) from public,anon; grant execute on function public.post_stock_movement(text,uuid,uuid,uuid,uuid,numeric,text,text,text) to authenticated;
